FeatureScript 3083;
import(path : "onshape/std/common.fs", version : "3083.0");

// Generated by fsgen (paste export). Paste into a Feature Studio, then add the feature
// to a Part Studio from the toolbar. Parameters appear in the feature dialog.

// Midpoint of an arc from its endpoints; k = tan(sweep / 4) keeps the arc's sweep when parameters change.
function arcMid(a is Vector, b is Vector, k is number) returns Vector
{
    var d = b - a;
    return (a + b) / 2 + vector(d[1], -d[0]) * (k / 2);
}

annotation { "Feature Type Name" : "H2 Minimal Car" }
export const h2MinimalCar = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Name" : "Length" }
        isLength(definition.length, { (millimeter) : [0, 180, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Width" }
        isLength(definition.width, { (millimeter) : [0, 90, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Body height" }
        isLength(definition.bodyHeight, { (millimeter) : [0, 37, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Wheelbase" }
        isLength(definition.wheelbase, { (millimeter) : [0, 130, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Wheel radius" }
        isLength(definition.wheelRadius, { (millimeter) : [0, 14, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Wheel thickness" }
        isLength(definition.wheelThickness, { (millimeter) : [0, 12, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Axle radius" }
        isLength(definition.axleRadius, { (millimeter) : [0, 4, 10000] } as LengthBoundSpec);
    }
    {
    // Chassis height
    // Chassis sketch
    var chassisSketchSk = newSketchOnPlane(context, id + "chassisSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter + ((20 * millimeter)) * vector(0, 0, 1), vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(chassisSketchSk, "outline_bottom", { "start" : vector(-definition.width / 2, -definition.length / 2), "end" : vector(definition.width / 2, -definition.length / 2) });
    skLineSegment(chassisSketchSk, "outline_right", { "start" : vector(definition.width / 2, -definition.length / 2), "end" : vector(definition.width / 2, definition.length / 2) });
    skLineSegment(chassisSketchSk, "outline_top", { "start" : vector(definition.width / 2, definition.length / 2), "end" : vector(-definition.width / 2, definition.length / 2) });
    skLineSegment(chassisSketchSk, "outline_left", { "start" : vector(-definition.width / 2, definition.length / 2), "end" : vector(-definition.width / 2, -definition.length / 2) });
    skSolve(chassisSketchSk);
    // Chassis
    opExtrude(context, id + "chassis" + "tool", { "entities" : qSketchRegion(id + "chassisSketch"), "direction" : vector(0, 0, 1), "endBound" : BoundingType.BLIND, "endDepth" : (8 * millimeter) });
    // Body height
    // Body sketch
    var bodySketchSk = newSketchOnPlane(context, id + "bodySketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter + ((28 * millimeter)) * vector(0, 0, 1), vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(bodySketchSk, "outline_bottom", { "start" : vector(-40, -60) * millimeter, "end" : vector(40, -60) * millimeter });
    skLineSegment(bodySketchSk, "outline_right", { "start" : vector(40, -60) * millimeter, "end" : vector(40, 60) * millimeter });
    skLineSegment(bodySketchSk, "outline_top", { "start" : vector(40, 60) * millimeter, "end" : vector(-40, 60) * millimeter });
    skLineSegment(bodySketchSk, "outline_left", { "start" : vector(-40, 60) * millimeter, "end" : vector(-40, -60) * millimeter });
    skSolve(bodySketchSk);
    // Body
    opExtrude(context, id + "body" + "tool", { "entities" : qSketchRegion(id + "bodySketch"), "direction" : vector(0, 0, 1), "endBound" : BoundingType.BLIND, "endDepth" : definition.bodyHeight });
    // Axle left plane
    // Axle sketch
    var axleSketchSk = newSketchOnPlane(context, id + "axleSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter + (-(55 * millimeter)) * vector(1, 0, 0), vector(1, 0, 0), vector(0, 1, 0)) });
    skCircle(axleSketchSk, "front", { "center" : vector(definition.wheelbase / 2, (15 * millimeter)), "radius" : definition.axleRadius });
    skCircle(axleSketchSk, "rear", { "center" : vector(-definition.wheelbase / 2, (15 * millimeter)), "radius" : definition.axleRadius });
    skSolve(axleSketchSk);
    // Axles
    opExtrude(context, id + "axles" + "tool", { "entities" : qSketchRegion(id + "axleSketch"), "direction" : vector(1, 0, 0), "endBound" : BoundingType.BLIND, "endDepth" : (110 * millimeter) });
    // Wheel left plane
    // Left wheel sketch
    var leftWheelSketchSk = newSketchOnPlane(context, id + "leftWheelSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter + (-definition.width / 2 - definition.wheelThickness) * vector(1, 0, 0), vector(1, 0, 0), vector(0, 1, 0)) });
    skCircle(leftWheelSketchSk, "front", { "center" : vector(definition.wheelbase / 2, (15 * millimeter)), "radius" : definition.wheelRadius });
    skCircle(leftWheelSketchSk, "rear", { "center" : vector(-definition.wheelbase / 2, (15 * millimeter)), "radius" : definition.wheelRadius });
    skSolve(leftWheelSketchSk);
    // Left wheels
    opExtrude(context, id + "leftWheels" + "tool", { "entities" : qSketchRegion(id + "leftWheelSketch"), "direction" : vector(1, 0, 0), "endBound" : BoundingType.BLIND, "endDepth" : definition.wheelThickness });
    // Wheel right plane
    // Right wheel sketch
    var rightWheelSketchSk = newSketchOnPlane(context, id + "rightWheelSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter + (definition.width / 2) * vector(1, 0, 0), vector(1, 0, 0), vector(0, 1, 0)) });
    skCircle(rightWheelSketchSk, "front", { "center" : vector(definition.wheelbase / 2, (15 * millimeter)), "radius" : definition.wheelRadius });
    skCircle(rightWheelSketchSk, "rear", { "center" : vector(-definition.wheelbase / 2, (15 * millimeter)), "radius" : definition.wheelRadius });
    skSolve(rightWheelSketchSk);
    // Right wheels
    opExtrude(context, id + "rightWheels" + "tool", { "entities" : qSketchRegion(id + "rightWheelSketch"), "direction" : vector(1, 0, 0), "endBound" : BoundingType.BLIND, "endDepth" : definition.wheelThickness });
    // remove the construction sketches and curves
    opDeleteBodies(context, id + "cleanupSketches", { "entities" : qUnion([qCreatedBy(id + "chassisSketch", EntityType.BODY), qCreatedBy(id + "bodySketch", EntityType.BODY), qCreatedBy(id + "axleSketch", EntityType.BODY), qCreatedBy(id + "leftWheelSketch", EntityType.BODY), qCreatedBy(id + "rightWheelSketch", EntityType.BODY)]) });
    });
